{{- /* GitHub Actions annotations: one workflow command per alert, so each
       shows up on the changed line in the pull request. Suggestions become
       notices, which GitHub shows without failing the check. */ -}}
{{- range .Files -}}
{{- $path := .Path -}}
{{- range .Alerts -}}
{{- $level := "notice" -}}
{{- if eq .Severity "error" -}}{{- $level = "error" -}}
{{- else if eq .Severity "warning" -}}{{- $level = "warning" -}}
{{- end -}}
::{{ $level }} file={{ $path }},line={{ .Line }},col={{ index .Span 0 }},endColumn={{ index .Span 1 }},title={{ .Check }}::{{ .Message }}
{{ end -}}
{{- end -}}

{{- /* JSON Lines: one object per alert, for a tool or an agent that reads
       alerts one at a time. Every field is JSON-encoded, so a message with a
       quote in it stays valid. */ -}}
{{- range .Files -}}
{{- $path := .Path -}}
{{- range .Alerts -}}
{{ dict "path" $path "line" .Line "column" (index .Span 0) "end" (index .Span 1) "check" .Check "severity" .Severity "message" .Message "match" .Match "link" .Link | toJson }}
{{ end -}}
{{- end -}}

{{- /* A Markdown summary, for a pull request comment or a job summary:
       a table per file, then the totals. */ -}}
{{- $e := 0 -}}{{- $w := 0 -}}{{- $s := 0 -}}
{{- range .Files -}}
### `{{ .Path }}`

| Line | Level | Rule | Message |
| ---: | ----- | ---- | ------- |
{{ range .Alerts -}}
{{- if eq .Severity "error" -}}{{- $e = add1 $e -}}
{{- else if eq .Severity "warning" -}}{{- $w = add1 $w -}}
{{- else -}}{{- $s = add1 $s -}}{{- end -}}
| {{ .Line }}:{{ index .Span 0 }} | {{ .Severity }} | `{{ .Check }}` | {{ .Message }} |
{{ end }}
{{ end -}}
**{{ $e }} {{ $e | int | plural "error" "errors" }}, {{ $w }} {{ $w | int | plural "warning" "warnings" }}, {{ $s }} {{ $s | int | plural "suggestion" "suggestions" }}.**
